<?php
require 'page-guard.php';require '../config/db_conn.php';require 'components.php';$id=(int)($_GET['id']??0);$section=$_SESSION['teacher-section'];$stmt=$conn->prepare('SELECT * FROM students WHERE ID=? AND SECTION=? LIMIT 1');$stmt->bind_param('is',$id,$section);$stmt->execute();$student=$stmt->get_result()->fetch_assoc();if(!$student){http_response_code(404);exit('Student not found.');}$log=$conn->prepare('SELECT TIME_IN FROM attendance WHERE TRIM(STUDENT_ID)=TRIM(?) ORDER BY TIME_IN DESC');$log->bind_param('s',$student['STUDENT_ID']);$log->execute();$records=$log->get_result();teacherHead('Student profile');teacherShell('Student profile'); ?>
<script>document.addEventListener('DOMContentLoaded',()=>{const link=document.querySelector('a[href*="export-attendance.php?student="]');if(!link)return;const url=new URL(link.href);url.searchParams.delete('date');url.searchParams.set('all_dates','1');link.href=url.toString();link.textContent='Export all dates'})</script>
<a href="students.php" class="text-sm font-bold text-blue-600">← Back to students</a><div class="mt-5 grid gap-7 lg:grid-cols-[320px_minmax(0,1fr)]"><aside class="h-fit rounded-2xl bg-white p-6 shadow-sm ring-1 ring-slate-200"><img src="../<?= htmlspecialchars($student['IMAGE_PATH']) ?>" alt="<?= htmlspecialchars($student['STUDENT_NAME']) ?>" class="aspect-square w-full rounded-2xl object-cover"><h2 class="mt-5 text-2xl font-black text-slate-900"><?= htmlspecialchars($student['STUDENT_NAME']) ?></h2><p class="mt-1 text-slate-500"><?= htmlspecialchars($student['STUDENT_ID']) ?></p><span class="mt-4 inline-block rounded-full bg-blue-50 px-3 py-1 text-sm font-bold text-blue-700"><?= htmlspecialchars($student['SECTION']) ?></span></aside><section class="overflow-hidden rounded-2xl bg-white shadow-sm ring-1 ring-slate-200"><div class="flex flex-wrap items-center justify-between gap-3 border-b border-slate-100 p-6"><div><h3 class="text-xl font-black text-slate-900">Attendance log</h3><p class="mt-1 text-sm text-slate-500">All recorded attendance for this student.</p></div><a href="export-attendance.php?student=<?= urlencode($student['STUDENT_ID']) ?>&date=<?= date('Y-m-d') ?>" class="rounded-xl bg-emerald-600 px-4 py-3 text-sm font-bold text-white">Export today</a></div><div class="overflow-x-auto"><table class="min-w-full text-left text-sm"><thead class="bg-slate-50 text-xs uppercase tracking-wider text-slate-500"><tr><th class="px-5 py-4">Date</th><th class="px-5 py-4">Time in</th><th class="px-5 py-4">Status</th></tr></thead><tbody class="divide-y divide-slate-100"><?php if($records->num_rows):while($record=$records->fetch_assoc()):$time=new DateTime($record['TIME_IN']);?><tr><td class="px-5 py-4 text-slate-700"><?= $time->format('F j, Y') ?></td><td class="px-5 py-4 text-slate-700"><?= $time->format('g:i A') ?></td><td class="px-5 py-4"><span class="rounded-full bg-emerald-50 px-3 py-1 text-xs font-bold text-emerald-700">Present</span></td></tr><?php endwhile;else:?><tr><td colspan="3" class="px-5 py-10 text-center text-slate-500">No attendance records found.</td></tr><?php endif; ?></tbody></table></div></section></div><?php teacherFoot(); ?>
